<?php require 'includes/functions.php';$title='Our community';require 'includes/header.php';?><section class="section"><div class="eyebrow">CONNECTED BY KINDNESS</div><h1>Meet our community.</h1><p>Approved orphanages working with donors to put good food to good use.</p><div class="cards"><?php $rows=query("SELECT name,city FROM users WHERE role='orphanage' AND status='approved' ORDER BY name")->fetchAll();foreach($rows as $o):?><article class="panel community-card"><span class="community-icon"><?=icon('heart')?></span><h3><?=e($o['name'])?></h3><p><?=icon('pin')?> <?=e($o['city'])?></p><span class="badge approved">Approved member</span></article><?php endforeach;if(!$rows)echo '<div class="empty">Our community is just getting started. Register your orphanage to join.</div>';?></div></section><?php require 'includes/footer.php';?>